{
  "kernel_id": "call_of_cthulhu_7e.rule_kernel.v1",
  "ruleset_id": "call_of_cthulhu_7e",
  "version": "v1_reader",
  "game_identity": {
    "summary": "Lovecraftian investigative horror run by a Keeper. The player characters are investigators who uncover clues, confront human and Mythos threats, and are typically pressured more by fear, uncertainty, and Sanity loss than by tactical victory. The game’s world identity is strongly rooted in H. P. Lovecraft’s cosmic horror: forbidden knowledge, fragile human understanding, and dangerous contact with the Cthulhu Mythos."
  },
  "play_loop": {
    "gm_procedures": "Keeper-facing play appears centered on managing investigation flow, clue delivery, pressure, and tone rather than encounter balance. From chapter 10 search hits, the Keeper is expected to adjudicate clue discovery and keep events moving even when players miss or misread evidence (p. 210-212), manage split scenes clearly (p. 211), and aim scenes toward consequences and mounting horror rather than 'winning' combats. Scene framing should therefore start at the next meaningful point of inquiry, danger, or revelation; if the investigators split up, the Keeper should be explicit about whose scene is active and cut between them at tense moments. Rolls are for uncertain, consequential actions; the snippets suggest the Keeper should especially consider how clue access works and avoid stalls around failed interpretation (p. 212). Minimal one-session prep: create a mystery with core clues, decide what the Mythos/human threat is doing if unopposed, prepare a small cast of witnesses/suspects, and line up a few scenes/locations where horror can escalate. Tone prep should emphasize cosmic dread, corruption, and helplessness over fair fights.",
    "subsystem_map": "Investigation/clue-gathering/social inquiry: central. This is the apparent default mode of play and the Keeper guidance in chapter 10 seems heavily focused on handling clues, scenes, and pacing.\nSanity/mental deterioration: central. Sanity is a defining pressure track and a major source of consequences for contact with the Mythos (chapter 8; also echoed at p. 166 and p. 184).\nCombat: one_of_several. Present and important when violence erupts, but not the game’s main center of gravity.\nChases: one_of_several. A featured procedural mode with dedicated setup and movement rules, used when pursuit matters.\nMagic/spell use: minor. Significant fictionally, but dangerous, specialized, and not everyday play; tied to Mythos contact.\nTomes/eldritch research: one_of_several. Important as a gateway to Mythos knowledge, spells, and Sanity risk; supports the investigation loop.\nCharacter creation/skills/general resolution: one_of_several. Core support systems underpin all play but are not the thematic heart compared with investigation plus Sanity."
  },
  "dice_core": {
    "compare": "roll_under",
    "compare_to": "the relevant skill or characteristic value; harder difficulties use fractions of that value",
    "dice": "1d100",
    "direction": "roll_under",
    "success_bands": [
      {
        "id": "hard",
        "label": "Hard success",
        "rank": 2,
        "semantics": "A stronger degree of success, showing notably capable performance. In opposed situations it beats a regular success and loses to an extreme or critical result.",
        "test": {
          "denominator": 2,
          "kind": "roll_under_fraction",
          "numerator": 1
        }
      },
      {
        "id": "regular",
        "label": "Regular success",
        "rank": 1,
        "semantics": "An ordinary success: the investigator achieves the intended task under the current difficulty.",
        "test": {
          "kind": "roll_under_or_equal"
        }
      },
      {
        "id": "failure",
        "label": "Failure",
        "rank": 0,
        "semantics": "The investigator does not achieve the stated goal; the Keeper narrates the failed outcome and may apply the stated consequences or allow a push where appropriate.",
        "test": {
          "kind": "otherwise"
        }
      },
      {
        "id": "extreme",
        "label": "Extreme",
        "semantics": "A result equal to or below one-fifth of the relevant skill or characteristic. It represents exceptional success, often the best possible non-critical performance and can determine impales or superior opposed outcomes."
      },
      {
        "id": "critical",
        "label": "Critical",
        "semantics": "An outstanding result, typically represented by a roll of 01. It is better than an extreme success and may produce especially decisive effects such as maximum added damage on an impale."
      },
      {
        "id": "fumble",
        "label": "Fumble",
        "semantics": "A catastrophic failure. It cannot be negated by spending Luck and invites severe negative consequences as appropriate to the action, especially in dangerous situations."
      }
    ],
    "success_rule": "Roll 1d100 and succeed if the result is equal to or less than the relevant rating; if a harder difficulty is called for, succeed only if the roll is equal to or less than the required fraction of that rating (explicitly, half for Hard).",
    "success_threshold": null,
    "summary": "Core resolution is percentile roll-under. When the Keeper calls for a roll, the player rolls 1d100 against the relevant skill or other rating. A result above the rating fails; a result equal to or below it succeeds. Difficulty can tighten the target by using a fraction of the rating rather than the full value: the pages read explicitly show a Hard success as rolling less than half the investigator’s Drive Auto skill. Sanity uses the same procedure: the Keeper calls for a Sanity roll, and on failure the investigator loses the listed amount for that encounter (example given: 0/1d6).",
    "target_face": null,
    "target_number": null
  },
  "check_model": {
    "compare": "roll_under",
    "compare_to": "the relevant skill or characteristic value; harder difficulties use fractions of that value",
    "direction": "roll_under",
    "success_rule": "Roll 1d100 and succeed if the result is equal to or less than the relevant rating; if a harder difficulty is called for, succeed only if the roll is equal to or less than the required fraction of that rating (explicitly, half for Hard).",
