  "damage_effect_model": {
    "derived_formulas": [
      {
        "depends_on": [
          "relevant_skill_or_sanity"
        ],
        "evaluator": "percentile_roll_under",
        "field_id": "regular_skill_or_sanity_roll",
        "formula": "1d100 <= relevant_skill_or_sanity",
        "notes": "Grounded by the Sanity roll example: 45 SAN, roll 83 = failure."
      },
      {
        "depends_on": [
          "relevant_skill"
        ],
        "evaluator": "percentile_roll_under",
        "field_id": "hard_roll",
        "formula": "1d100 <= floor(relevant_skill/2)",
        "notes": "Grounded by p96: success is rolling less than half the investigator's Drive Auto skill."
      },
      {
        "depends_on": [
          "current_sanity",
          "listed_failed_san_loss"
        ],
        "evaluator": "resource_subtract",
        "field_id": "sanity_loss_on_failed_sanity_roll",
        "formula": "current_sanity -= listed_failed_san_loss",
        "notes": "For encounters, Sanity loss is stated as a success/failure pair such as 0/1d6."
      },
      {
        "depends_on": [
