    {
      "id": "call_of_cthulhu_7e.bonus_and_penalty_dice",
      "name": "Bonus and penalty dice",
      "kind": "reaction",
      "description": "A modifier procedure that shifts a percentile roll in the player's favor or against them by rolling extra tens dice and keeping the best or worst tens result.",
      "when_to_use": "Use when circumstances give a distinct advantage or disadvantage to a roll, such as favorable position, poor conditions, or situational hindrance judged by the Keeper.",
      "tested_parameter": null,
      "procedure": [
        {
          "step": "gate",
          "condition": "Decide whether the situation grants bonus dice, penalty dice, or both.",
          "note": "One bonus die and one penalty die cancel each other out."
        },
        {
          "step": "roll",
          "dice": "1d100 with extra tens die or dice",
          "vs": "the underlying skill or characteristic target",
          "note": "For a bonus die keep the lower tens result; for a penalty die keep the higher tens result."
        },
        {
          "step": "gate",
          "condition": "If conditions are exceptionally favorable or dire, use a second bonus or penalty die.",
