          "condition": "At the start of combat, ask each player what their investigator is doing in the fiction.",
          "note": "Description comes before game terms."
        },
        {
          "step": "roll",
          "dice": "1d100",
          "vs": "DEX for initiative under the optional initiative system, or use the default ordering for combatants as applicable",
          "note": "Determine who acts first when needed."
        },
        {
          "step": "gate",
          "condition": "On each turn, determine required rolls from the declared action, resolve them, then feed the outcome back into the fiction.",
