      "name": "Resolve a melee attack",
      "kind": "subsystem_procedure",
      "description": "A melee attack is an opposed exchange in which the target chooses to dodge or fight back, and the higher success level decides the outcome.",
      "when_to_use": "Use when one character makes a Fighting attack against a target in reach during combat.",
      "tested_parameter": "Fighting (Any)",
      "procedure": [
        {
          "step": "gate",
          "condition": "The defender chooses either to dodge or to fight back.",
          "note": "Use Dodge if evading; use an appropriate Fighting skill if countering."
        },
        {
          "step": "roll",
          "dice": "1d100",
          "vs": "attacker's Fighting skill",
          "note": "Make the attack roll."
        },
        {
          "step": "roll",
          "dice": "1d100",
          "vs": "defender's Dodge or Fighting skill",
          "note": "Resolve the chosen response."
