      "id": "call_of_cthulhu_7e.medicine_treatment",
      "name": "Medicine treatment",
      "kind": "subsystem_procedure",
      "description": "Longer-form medical treatment can restore more hit points than First Aid and is required to properly stabilize a dying patient after emergency aid.",
      "when_to_use": "Use when a character receives sustained medical care at least an hour long after taking damage.",
      "tested_parameter": "Medicine",
      "procedure": [
        {
          "step": "roll",
          "dice": "1d100",
          "vs": "Medicine",
          "note": "Treatment takes at least one hour; if not performed on the same day, require Hard difficulty."
        },
        {
          "step": "gate",
          "condition": "If successful, restore 1D3 hit points in addition to any First Aid already received.",
          "note": "A character is limited to one successful Medicine treatment for the injury until further damage is taken."
        },
        {
          "step": "gate",
          "condition": "A dying character must first receive successful First Aid before Medicine can stabilize them.",
          "note": "Medicine alone is not the first step in saving a dying patient."
        }
