    {
      "id": "call_of_cthulhu_7e.opposed_roll",
      "name": "Opposed roll",
      "kind": "subsystem_procedure",
      "description": "A contest where two sides pursue mutually exclusive goals and both attempt a roll to see whose effort prevails.",
      "when_to_use": "Use when one character's success directly means the other's failure, such as a contest of wits, force, or social influence, and the situation cannot simply be retried after the result is known.",
      "tested_parameter": null,
      "procedure": [
        {
          "step": "gate",
          "condition": "Identify the two opposed goals and choose the relevant skill or characteristic for each side.",
          "note": "Use the traits that best match how each side is contesting the situation."
        },
        {
          "step": "roll",
          "dice": "1d100",
          "vs": "each side's relevant skill or characteristic",
          "note": "Each side rolls once."
        },
        {
          "step": "gate",
          "condition": "Compare levels of success to determine the winner.",
          "note": "Higher success level wins; if both achieve the same level, the higher skill or characteristic wins."
        }
      ],
