    {
      "id": "call_of_cthulhu_7e.push_skill_roll",
      "name": "Push a skill roll",
      "kind": "reaction",
      "description": "A player may turn a failed non-combat skill attempt into a riskier renewed effort, with higher stakes if it fails.",
      "when_to_use": "Use after a failed skill roll when the investigator could plausibly try again with more effort, more time, or greater risk, and the Keeper is willing to define a meaningful consequence for failure.",
      "tested_parameter": null,
      "procedure": [
        {
          "step": "gate",
          "condition": "The original roll was a skill roll, not a combat roll, and the investigator can justify a renewed attempt with increased risk or commitment.",
          "note": "Combat rolls cannot be pushed."
        },
        {
          "step": "gate",
          "condition": "The player has not spent Luck on the failed roll.",
          "note": "A failed skill roll can be pushed or modified by Luck, but not both."
        },
        {
          "step": "roll",
          "dice": "1d100",
          "vs": "same skill at the same difficulty unless circumstances have changed",
          "note": "Resolve as a second attempt."
        },
        {
          "step": "gate",
          "condition": "If the pushed roll fails, apply a serious consequence appropriate to the method and situation.",
          "note": "The book emphasizes fiction-driven consequences, often worse if the investigator is insane."
        }
      ],
