    {
      "id": "call_of_cthulhu_7e.ranged_and_thrown_attack_resolution",
      "name": "Resolve a ranged or thrown attack",
      "kind": "subsystem_procedure",
      "description": "Procedure for attacks made with firearms, bows, or thrown weapons, including which defensive options apply and how movement and cover interact with the shot.",
      "when_to_use": "Use when a combatant attacks from range with a firearm, missile weapon, or thrown object.",
      "tested_parameter": null,
      "procedure": [
        {
          "step": "gate",
          "condition": "Set the attack's difficulty from range and circumstances.",
          "note": "Thrown and missile attacks use firearm-style difficulty setting."
        },
        {
          "step": "gate",
          "condition": "Determine the defender's options.",
          "note": "Missile attacks may be answered with Dive for Cover; thrown weapons may be opposed with Dodge like a fighting attack. A character cannot fight back against a ranged or thrown attack unless within one-fifth of their DEX in feet of the attacker."
        },
        {
          "step": "roll",
          "dice": "1d100",
          "vs": "the relevant ranged attack skill at the set difficulty",
          "note": "Resolve the hit roll after applying any situational modifiers."
        },
        {
          "step": "gate",
          "condition": "If moving with a firearm, apply the movement limits for when the shot occurs.",
          "note": "A readied firearm gains the +50 DEX benefit only before any movement; moving up to MOV allows a normal firearms attack on usual DEX rank; moving up to MOV×5 means firing while running and losing that advantage."
        }
