      "id": "call_of_cthulhu_7e.reality_check_underlying_insanity",
      "name": "Reality check during underlying insanity",
      "kind": "reaction",
      "description": "An investigator suffering underlying insanity may challenge a possible delusion with a Sanity roll to determine what is really there.",
      "when_to_use": "Use when an investigator under underlying insanity doubts what they are perceiving and asks whether an apparent sight or event is real.",
      "tested_parameter": "sanity",
      "procedure": [
        {
          "step": "roll",
          "dice": "1d100",
          "vs": "current Sanity",
          "note": "Make a reality check."
        },
        {
          "step": "gate",
          "condition": "On success, the investigator sees through the delusion and the Keeper must describe reality accurately.",
          "note": "They resist further delusions until they lose more Sanity."
        },
        {
          "step": "gate",
          "condition": "On failure, lose 1 Sanity point.",
          "note": "If the investigator is suffering underlying insanity, this immediately induces a bout of madness."
        }
      ],
