          "dice": "1d100",
          "vs": "current Sanity",
          "note": "Make a Sanity roll."
        },
        {
          "step": "gate",
          "condition": "On success, apply the lower listed Sanity loss if any.",
          "note": "The exact amount depends on the encounter."
        },
        {
          "step": "gate",
          "condition": "On failure, apply the higher listed Sanity loss.",
          "note": "The player or Keeper rolls the listed loss amount when needed."
