    {
      "id": "call_of_cthulhu_7e.self_help_sanity_recovery",
      "name": "Self-help Sanity recovery",
      "kind": "subsystem_procedure",
      "description": "During downtime or development, an investigator may seek healing through meaningful backstory connections or personal restoration scenes.",
      "when_to_use": "Use between adventures or during the investigator development phase when the player describes a thematically appropriate attempt at healing or redemption.",
      "tested_parameter": "sanity",
      "procedure": [
        {
          "step": "gate",
          "condition": "Roleplay or describe what the investigator is doing to recover, tied to their backstory or key connection.",
          "note": "Examples include a retreat, holiday, or reconnecting with a loved one."
        },
        {
          "step": "roll",
          "dice": "1d100",
          "vs": "current Sanity",
          "note": "Make a Sanity roll; use a bonus die if the investigator is using their key connection."
        },
        {
          "step": "gate",
          "condition": "On success, recover 1D6 Sanity points.",
          "note": "If the key connection was used, the investigator also recovers from indefinite insanity."
        },
        {
          "step": "gate",
          "condition": "On failure, lose 1 Sanity point and revise that backstory aspect to reflect the failed attempt.",
          "note": "If the failed aspect was the key connection, it is lost."
        }
      ],
      "hooks": [
        {
          "event": "development_phase"
