      "id": "call_of_cthulhu_7e.spend_luck_after_roll",
      "name": "Spend Luck after a roll",
      "kind": "spend",
      "description": "Luck points can be spent on a 1-for-1 basis to improve the result of the investigator’s own skill or characteristic roll after seeing the dice.",
      "when_to_use": "Use immediately after the investigator makes a skill or characteristic roll and before the fiction moves on, when a better success band would matter and the roll is eligible for Luck spending.",
      "tested_parameter": "luck",
      "procedure": [
        {
          "step": "gate",
          "condition": "The roll must be the investigator’s own skill or characteristic roll.",
          "note": "Luck cannot alter another character’s roll."
        },
        {
          "step": "gate",
          "condition": "The roll must not be a Luck roll, damage roll, Sanity roll, Sanity-loss amount roll, or a pushed roll.",
          "note": "Criticals, fumbles, and firearm malfunctions still stand."
        },
        {
          "step": "apply",
          "track": "luck",
          "op": "subtract",
          "amount": "as many points as needed on a 1-for-1 basis",
          "note": "Deduct Luck equal to the amount by which the rolled value must be lowered."
        },
        {
          "step": "gate",
          "condition": "Change the roll result accordingly and resolve the new outcome band.",
          "note": "No skill improvement check is earned if Luck changed the roll."
        }
      ],
      "hooks": [],
      "passive_projection": "Luck {value}",
      "followup_links": [],
