      "name": "Temporary insanity trigger",
      "kind": "subsystem_procedure",
      "description": "A large immediate Sanity loss can force the investigator to grasp the full significance of the horror and thereby become temporarily insane.",
      "when_to_use": "Use when an investigator loses 5 or more Sanity points from a single shock.",
      "tested_parameter": "int",
      "procedure": [
        {
          "step": "gate",
          "condition": "The investigator has lost 5 or more Sanity points at one time.",
          "note": "This is the trigger threshold."
        },
        {
          "step": "roll",
          "dice": "1d100",
          "vs": "INT",
          "note": "Roll to see whether the investigator fully comprehends what was experienced."
        },
        {
          "step": "gate",
          "condition": "If the INT roll succeeds, temporary insanity begins immediately and lasts 1D10 hours.",
          "note": "Proceed to a bout of madness."
        },
        {
          "step": "gate",
          "condition": "If the INT roll fails, the memory is repressed and the investigator does not become insane from this trigger.",
          "note": "The Sanity loss still stands."
        }
      ],
